create extension if not exists pgcrypto;
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz default now());
create or replace function public.is_admin() returns boolean language sql security definer set search_path=public stable as $$select exists(select 1 from public.admin_users where user_id=auth.uid())$$;
create table if not exists public.business_info(id uuid primary key default gen_random_uuid(),name text not null default 'Sabor & Cia',logo_letter text default 'S',logo_url text,tagline text default 'Cardápio digital',whatsapp text default '',main_title text default 'Escolha seus favoritos',description text default '',instagram text default '',address text default '',footer_text text default 'Todos os direitos reservados.',updated_at timestamptz default now());
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,support_text text default '',sort_order int not null default 1,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),category_id uuid not null references public.categories(id) on delete restrict,name text not null,description text default '',price numeric(10,2) not null default 0,image_url text,sort_order int not null default 1,available boolean not null default true,created_at timestamptz default now(),updated_at timestamptz default now());
alter table public.admin_users enable row level security;alter table public.business_info enable row level security;alter table public.categories enable row level security;alter table public.products enable row level security;
drop policy if exists public_read_info on public.business_info;create policy public_read_info on public.business_info for select using(true);
drop policy if exists admin_insert_info on public.business_info;create policy admin_insert_info on public.business_info for insert with check(public.is_admin());drop policy if exists admin_update_info on public.business_info;create policy admin_update_info on public.business_info for update using(public.is_admin()) with check(public.is_admin());
drop policy if exists public_read_categories on public.categories;create policy public_read_categories on public.categories for select using(true);drop policy if exists admin_insert_categories on public.categories;create policy admin_insert_categories on public.categories for insert with check(public.is_admin());drop policy if exists admin_update_categories on public.categories;create policy admin_update_categories on public.categories for update using(public.is_admin()) with check(public.is_admin());drop policy if exists admin_delete_categories on public.categories;create policy admin_delete_categories on public.categories for delete using(public.is_admin());
drop policy if exists public_read_products on public.products;create policy public_read_products on public.products for select using(available=true or public.is_admin());drop policy if exists admin_insert_products on public.products;create policy admin_insert_products on public.products for insert with check(public.is_admin());drop policy if exists admin_update_products on public.products;create policy admin_update_products on public.products for update using(public.is_admin()) with check(public.is_admin());drop policy if exists admin_delete_products on public.products;create policy admin_delete_products on public.products for delete using(public.is_admin());
insert into storage.buckets(id,name,public) values('product-images','product-images',true) on conflict(id) do nothing;
drop policy if exists public_read_images on storage.objects;create policy public_read_images on storage.objects for select using(bucket_id='product-images');drop policy if exists admin_upload_images on storage.objects;create policy admin_upload_images on storage.objects for insert with check(bucket_id='product-images' and public.is_admin());drop policy if exists admin_update_images on storage.objects;create policy admin_update_images on storage.objects for update using(bucket_id='product-images' and public.is_admin()) with check(bucket_id='product-images' and public.is_admin());drop policy if exists admin_delete_images on storage.objects;create policy admin_delete_images on storage.objects for delete using(bucket_id='product-images' and public.is_admin());
